python3 - <<'PY'
import csv, json, math
from pathlib import Path
root=Path('/root')
with open(root/'syncpack_analysis.json', encoding='utf-8') as f:
    data=json.load(f)
expected_assumptions={
    'patients':180,
    'capsules_per_fill_28':56,
    'fills_28':12,
    'capsules_per_fill_56':112,
    'fills_56':6,
    'decision_threshold_usd':9000,
}
required_med_fields={
    'medication','price_per_1000_capsules_usd','blister_card_count','card_cost_usd',
    'reimbursement_per_cycle_180_patients_usd','annual_drug_cost_28','annual_drug_cost_56',
    'annual_packaging_cost_28','annual_packaging_cost_56','annual_reimbursement_28',
    'annual_reimbursement_56','annual_margin_28','annual_margin_56','margin_difference'
}
currency_fields=required_med_fields-{'medication','blister_card_count'}
errors=[]
if data.get('assumptions') != expected_assumptions:
    errors.append(f'assumptions mismatch: {data.get("assumptions")}')
meds=data.get('medications', [])
med_names=[m.get('medication') for m in meds]
if med_names != sorted(med_names):
    errors.append(f'medications not sorted: {med_names}')
for i,m in enumerate(meds):
    if set(m.keys()) != required_med_fields:
        errors.append(f'medication {i} fields mismatch: {sorted(m.keys())}')
    for field in currency_fields:
        v=m.get(field)
        if not isinstance(v,(int,float)) or round(v,2) != v:
            errors.append(f'{m.get("medication")} {field} not rounded numeric: {v!r}')
expected_totals={'total_annual_margin_28','total_annual_margin_56','total_difference','absolute_total'}
totals=data.get('totals', {})
if set(totals.keys()) != expected_totals:
    errors.append(f'totals fields mismatch: {totals.keys()}')
for k,v in totals.items():
    if not isinstance(v,(int,float)) or round(v,2) != v:
        errors.append(f'total {k} not rounded numeric: {v!r}')
if data.get('recommendation',{}).get('decision') not in {'convert_to_56_day','keep_28_day'}:
    errors.append(f'bad decision {data.get("recommendation",{}).get("decision")}')
# summary check
lines=[line.strip() for line in (root/'syncpack_summary.md').read_text(encoding='utf-8').splitlines() if line.strip()]
if not 4 <= len(lines) <= 8:
    errors.append(f'summary line count {len(lines)}')
summary='\n'.join(lines)
for needle in ['Total 28-day margin', 'Total 56-day margin', 'Absolute difference', data['recommendation']['decision']]:
    if needle not in summary:
        errors.append(f'summary missing {needle!r}')
# spot-check first medication alphabetically annual_drug_cost_28
with open(root/'ingredient_cost.csv', newline='', encoding='utf-8') as f:
    ingredient={r['medication']: r for r in csv.DictReader(f)}
first=meds[0]
source=ingredient[first['medication']]
calc=round((float(source['price_per_1000_capsules_usd'])/1000)*56*12*180,2)
if calc != first['annual_drug_cost_28']:
    errors.append(f'spot check mismatch {first["medication"]}: calc {calc}, json {first["annual_drug_cost_28"]}')
print('VALIDATION_STATUS:', 'PASS' if not errors else 'FAIL')
print('Medication count:', len(meds))
print('First medication:', first['medication'])
print('Spot-check annual_drug_cost_28:', f"({source['price_per_1000_capsules_usd']}/1000)*56*12*180 = {calc}")
print('Totals:', totals)
print('Decision:', data['recommendation']['decision'])
if errors:
    print('ERRORS:')
    for e in errors:
        print('-', e)
    raise SystemExit(1)
PY

